const pkg = $('Prepare Proposal Package').first().json;
const input = $input.item.json;
const biz = $('Normalize Vapi Payload').first().json;

// ================= helpers =================
const clean = s => String(s ?? '').replace(/\*\*/g, '').replace(/`/g, '').replace(/\s+/g, ' ').trim();
const trunc = (s, max) => {
  s = clean(s);
  if (s.length <= max) return s;
  const cut = s.slice(0, max);
  let best = -1, mark = '';
  for (const m of ['. ', '; ', ' — ', ' (', ': ', ', ']) { const k = cut.lastIndexOf(m); if (k > best && k > max * 0.5) { best = k; mark = m; } }
  if (best > 0) return cut.slice(0, best).replace(/[,;:\-–—(\s]+$/, '') + (mark === '. ' ? '.' : '.');
  const sp = cut.lastIndexOf(' ');
  return cut.slice(0, sp > 0 ? sp : max).replace(/[,;:\-–—(]+$/, '') + '…';
};
// largest font size that fits the box; trims at a clean boundary only as a last resort
const fit = (txt, w, h, max, min = 10, bold = false) => {
  txt = clean(txt);
  const iw = Math.max(20, w - 14), ih = Math.max(10, h - 8), k = bold ? 0.58 : 0.53;
  for (let s = max; s >= min; s -= 0.5) {
    const cpl = Math.max(1, Math.floor(iw / (s * k)));
    if (Math.ceil(txt.length / cpl) * s * 1.22 <= ih) return { txt, size: s };
  }
  const cpl = Math.max(1, Math.floor(iw / (min * k)));
  const lines = Math.max(1, Math.floor(ih / (min * 1.22)));
  return { txt: trunc(txt, cpl * lines - 6), size: min };
};

// evidence tags the AI appends, e.g. "(Confirmed)" or "(To be validated in technical discovery)"
const TAG_KEYS = /confirm|validat|proposed|recommended|observed|decision|source|assumption|risk|acceptance|criteria|dependency|measure/i;
const splitTag = raw => {
  let t = clean(raw), tag = '';
  for (let i = 0; i < 3; i++) {
    const m = t.match(/\s*\(([^()]*)\)\s*\.?\s*$/);
    if (!m || !TAG_KEYS.test(m[1])) break;
    const x = m[1].toLowerCase();
    if (!tag) {
      if (/validat|confirm access|confirm with|confirm parsing|confirm acceptable|to be confirmed|pending|candidate/.test(x)) tag = 'TO CONFIRM';
      else if (/proposed/.test(x)) tag = 'PROPOSED';
      else if (/^confirmed|confirmed from|source: discovery|assumption — confirmed|^observed/.test(x)) tag = 'CONFIRMED';
      else if (/recommended/.test(x)) tag = 'RECOMMENDED';
    }
    t = t.slice(0, m.index).replace(/[\s;,]+$/, '');
    if (!/[.!?…]$/.test(t)) t += '.';
  }
  return { text: t, tag };
};
const LABELS = [
  [/^observed/i, 'What we heard'], [/^business impact/i, 'Why it matters'], [/^gap/i, 'The gap'],
  [/^opportunity/i, 'Opportunity'], [/^recommended/i, 'Our recommendation'], [/^measure/i, 'How we will measure'],
  [/^dependency/i, 'What we need'], [/^decision/i, 'Decision needed'], [/^risks?/i, 'Key risks'],
  [/^assumptions?/i, 'Assumptions'], [/^pricing/i, 'Investment and timing'], [/^to validate|^validation/i, 'To confirm'],
  [/^next action|^next step/i, 'Next step'], [/^confirmed systems/i, 'Systems in scope'], [/^candidate integration/i, 'To be confirmed']
];
const niceLabel = l => { l = clean(l); if (!l) return ''; const first = l.split('/')[0].trim(); for (const [rx, v] of LABELS) if (rx.test(first)) return v; return first.charAt(0).toUpperCase() + first.slice(1); };

const clientRaw = clean(biz.business_name || biz.customer_name || '');
const client = clientRaw || 'Prospective Client';
const clientUp = client.toUpperCase();
const forLine = clientRaw ? '  •  PREPARED FOR ' + clientUp : '';
const needText = clean(biz.business_need || biz.desired_outcome || 'To be confirmed in technical discovery');
const systems = (Array.isArray(biz.systems_mentioned) ? biz.systems_mentioned : String(biz.systems_mentioned || '').split(/[,;]\s*/)).map(clean).filter(Boolean);
const systemsLabel = systems.slice(0, 4).join(' • ') || 'To be confirmed';
const contactLine = [clean(biz.customer_name), clean(biz.customer_role)].filter(Boolean).join(' • ') || 'To be confirmed';
const dateLabel = $now.toFormat('LLLL d, yyyy');

// ================= parse the AI proposal =================
const raw = String(pkg.proposal_text ?? '').split(/\r?\n/);
const sections = [];
let cur = null;
for (const line of raw) {
  const m = line.match(/^\s{0,3}#{1,3}\s+(.+)$/);
  if (m) { if (cur) sections.push(cur); cur = { heading: clean(m[1].replace(/^\d+[.)]\s*/, '')), lines: [] }; }
  else if (cur && line.trim()) cur.lines.push(line);
}
if (cur) sections.push(cur);

const parsed = sections.map(s => {
  let headline = '';
  const items = [];
  for (const l of s.lines) {
    const numbered = /^\s*\d+[.)]\s+/.test(l);
    const t0 = clean(l.replace(/^\s*[-*•]\s+/, '').replace(/^\s*\d+[.)]\s+/, ''));
    if (!t0) continue;
    if (/^headline\s*:/i.test(t0)) { headline = splitTag(t0.replace(/^headline\s*:\s*/i, '')).text; continue; }
    const lm = t0.match(/^([A-Za-z][A-Za-z0-9 \/&+—-]{1,64}):\s+(.+)$/);
    const body = splitTag(lm ? lm[2] : t0);
    items.push({ label: lm ? niceLabel(lm[1]) : '', rawLabel: lm ? lm[1] : '', text: body.text, tag: body.tag, numbered });
  }
  if (!headline && items.length) headline = items[0].text;
  return { heading: s.heading, headline: trunc(headline || s.heading, 150), items };
}).filter(s => s.items.length || s.headline).slice(0, 8);

if (!parsed.length) {
  parsed.push({ heading: 'Proposal Summary', headline: 'A practical starting point for a more connected operation', items: [
    { label: 'Next step', text: 'Confirm the current process and business priority.', tag: '', numbered: false },
    { label: 'What we need', text: 'Validate system access and integration options.', tag: '', numbered: false },
    { label: 'How we will measure', text: 'Agree measurable acceptance criteria before implementation.', tag: '', numbered: false }] });
}
const total = parsed.length + 1;

// ================= palette & primitives =================
const C = {
  bg: { red: 0.025, green: 0.04, blue: 0.075 }, panel: { red: 0.06, green: 0.09, blue: 0.15 }, panel2: { red: 0.085, green: 0.13, blue: 0.21 },
  green: { red: 0.12, green: 0.82, blue: 0.48 }, cyan: { red: 0.20, green: 0.75, blue: 0.95 }, white: { red: 0.96, green: 0.98, blue: 1 },
  muted: { red: 0.67, green: 0.74, blue: 0.84 }, orange: { red: 1, green: 0.66, blue: 0.28 }, line: { red: 0.16, green: 0.24, blue: 0.36 }
};
const TAGCOL = { 'CONFIRMED': C.green, 'TO CONFIRM': C.orange, 'PROPOSED': C.cyan, 'RECOMMENDED': C.cyan };
const req = [];
const addShape = (sid, oid, x, y, w, h, fill, type = 'ROUND_RECTANGLE') => {
  req.push(
    { createShape: { objectId: oid, shapeType: type, elementProperties: { pageObjectId: sid, size: { width: { magnitude: w, unit: 'PT' }, height: { magnitude: h, unit: 'PT' } }, transform: { scaleX: 1, scaleY: 1, translateX: x, translateY: y, unit: 'PT' } } } },
    { updateShapeProperties: { objectId: oid, shapeProperties: { shapeBackgroundFill: { solidFill: { color: { rgbColor: fill }, alpha: 1 } }, outline: { propertyState: 'NOT_RENDERED' } }, fields: 'shapeBackgroundFill,outline' } });
};
const styleText = (oid, size, color, bold, align) => {
  req.push({ updateTextStyle: { objectId: oid, textRange: { type: 'ALL' }, style: { fontFamily: 'Arial', fontSize: { magnitude: size, unit: 'PT' }, bold, foregroundColor: { opaqueColor: { rgbColor: color } } }, fields: 'fontFamily,fontSize,bold,foregroundColor' } });
  if (align && align !== 'START') req.push({ updateParagraphStyle: { objectId: oid, textRange: { type: 'ALL' }, style: { alignment: align }, fields: 'alignment' } });
};
const addText = (sid, oid, txt, x, y, w, h, size, color, bold = false, align = 'START') => {
  txt = String(txt ?? '');
  req.push({ createShape: { objectId: oid, shapeType: 'TEXT_BOX', elementProperties: { pageObjectId: sid, size: { width: { magnitude: w, unit: 'PT' }, height: { magnitude: h, unit: 'PT' } }, transform: { scaleX: 1, scaleY: 1, translateX: x, translateY: y, unit: 'PT' } } } });
  if (!txt) return;
  req.push({ insertText: { objectId: oid, insertionIndex: 0, text: txt } });
  styleText(oid, size, color, bold, align);
};
const addFit = (sid, oid, txt, x, y, w, h, max, min, color, bold = false) => {
  const f = fit(txt, w, h, max, min, bold);
  addText(sid, oid, f.txt, x, y, w, h, f.size, color, bold);
};
// filled shape that carries its own centred text (badges, chips, flow boxes)
const addBadge = (sid, oid, x, y, w, h, fill, txt, size, color, bold = true, type = 'ELLIPSE') => {
  addShape(sid, oid, x, y, w, h, fill, type);
  if (!txt) return;
  req.push({ insertText: { objectId: oid, insertionIndex: 0, text: String(txt) } });
  styleText(oid, size, color, bold, 'CENTER');
  req.push({ updateShapeProperties: { objectId: oid, shapeProperties: { contentAlignment: 'MIDDLE' }, fields: 'contentAlignment' } });
};
const addChip = (sid, p, x, y, tag) => {
  if (!tag) return;
  const w = 8 + tag.length * 5.6;
  addBadge(sid, p + '_chip', x - w, y, w, 13, TAGCOL[tag] || C.cyan, tag, 7, C.bg, true, 'ROUND_RECTANGLE');
};
const addBase = (sid, n, heading, headline) => {
  req.push({ createSlide: { objectId: sid, slideLayoutReference: { predefinedLayout: 'BLANK' } } },
    { updatePageProperties: { objectId: sid, pageProperties: { pageBackgroundFill: { solidFill: { color: { rgbColor: C.bg }, alpha: 1 } } }, fields: 'pageBackgroundFill' } });
  addText(sid, 'brand_' + n, 'YOUR AGENCY  /  AI AUTOMATION', 36, 16, 300, 16, 9, C.green, true);
  addFit(sid, 'kicker_' + n, ('AUTOMATION AUDIT & PROPOSAL' + (clientRaw ? '  •  ' + clientUp : '')).slice(0, 90), 36, 32, 640, 16, 8, 7, C.muted, true);
  addShape(sid, 'accent_' + n, 36, 56, 48, 4, C.green, 'RECTANGLE');
  addFit(sid, 'title_' + n, heading, 36, 64, 640, 34, 24, 16, C.white, true);
  addFit(sid, 'headline_' + n, headline, 36, 100, 648, 46, 14, 11, C.cyan, true);
  addText(sid, 'footer_' + n, 'DRAFT FOR DISCUSSION  •  CONFIDENTIAL' + forLine + '  •  YOUR AGENCY', 36, 384, 560, 14, 7, C.muted, false);
  addText(sid, 'page_' + n, String(n).padStart(2, '0') + ' / ' + String(total).padStart(2, '0'), 600, 382, 84, 16, 8, C.green, true, 'END');
};
// content card: coloured stripe, caps label, body text, optional evidence chip
const addCard = (sid, p, x, y, w, h, label, body, accent = C.green, max = 12, tag = '') => {
  addShape(sid, p + '_card', x, y, w, h, C.panel, 'RECTANGLE');
  addShape(sid, p + '_stripe', x, y, 4, h, accent, 'RECTANGLE');
  addFit(sid, p + '_label', String(label).toUpperCase(), x + 12, y + 6, w - 22 - (tag ? 70 : 0), 16, 9, 8, accent, true);
  addChip(sid, p, x + w - 8, y + 9, tag);
  addFit(sid, p + '_body', body, x + 12, y + 24, w - 22, h - 28, max, 10, C.white, false);
};
const stack = (sid, p, items, x, y, w, totalH, gap, defaults, max = 12) => {
  const n = items.length; if (!n) return;
  const h = (totalH - gap * (n - 1)) / n;
  items.forEach((it, j) => addCard(sid, p + '_' + j, x, y + j * (h + gap), w, h, it.label || defaults[j] || 'Detail', it.text, j % 2 ? C.cyan : C.green, max, it.tag));
};
const sidePanel = (sid, p, x, y, w, h, label, lines) => {
  addShape(sid, p + '_panel', x, y, w, h, C.panel2);
  addText(sid, p + '_label', label, x + 14, y + 10, w - 28, 16, 9, C.green, true);
  const avail = h - 40, tw = lines.reduce((a, l) => a + (l.wt || 1), 0);
  let yy = y + 32;
  lines.forEach((ln, j) => {
    const seg = avail * (ln.wt || 1) / tw, hh = seg - 4;
    addText(sid, p + '_k' + j, ln.k, x + 14, yy, w - 28, 13, 8, C.cyan, true);
    addFit(sid, p + '_v' + j, ln.v, x + 14, yy + 13, w - 28, hh - 11, 12, 9, C.white, true);
    yy += seg;
  });
};

// ================= cover slide =================
const firstSlide = (input.slides ?? [])[0];
const cover = firstSlide?.objectId || 'deck_cover';
if (firstSlide) (firstSlide.pageElements ?? []).forEach(e => { if (e?.objectId) req.push({ deleteObject: { objectId: e.objectId } }); });
else req.push({ createSlide: { objectId: cover, slideLayoutReference: { predefinedLayout: 'BLANK' } } });
req.push({ updatePageProperties: { objectId: cover, pageProperties: { pageBackgroundFill: { solidFill: { color: { rgbColor: C.bg }, alpha: 1 } } }, fields: 'pageBackgroundFill' } });
addShape(cover, 'cover_orbit1', 520, 30, 155, 155, C.panel2, 'ELLIPSE');
addShape(cover, 'cover_orbit2', 558, 68, 80, 80, C.green, 'ELLIPSE');
addShape(cover, 'cover_orbit3', 579, 89, 38, 38, C.bg, 'ELLIPSE');
addShape(cover, 'cover_orbit4', 506, 150, 22, 22, C.cyan, 'ELLIPSE');
addText(cover, 'cover_brand', 'YOUR AGENCY  /  AI AUTOMATION AGENCY', 44, 40, 440, 22, 12, C.green, true);
addText(cover, 'cover_label', 'DISCOVERY AUDIT  +  PROPOSAL', 44, 96, 440, 20, 10, C.cyan, true);
addFit(cover, 'cover_title', 'Automation Audit & Proposal', 44, 122, 470, 52, 36, 24, C.white, true);
addFit(cover, 'cover_client_title', clientRaw ? 'Prepared for ' + clientRaw : 'Prepared following your discovery call', 44, 180, 470, 30, 20, 12, C.green, true);
addFit(cover, 'cover_subtitle', 'A practical plan to remove operational friction, connect the right systems and make improvement measurable.', 44, 218, 470, 56, 14, 11, C.muted, false);
addShape(cover, 'cover_client_card', 44, 300, 632, 62, C.panel);
addText(cover, 'cover_client_label', 'PREPARED FOR', 58, 310, 130, 14, 8, C.green, true);
addFit(cover, 'cover_client', client, 58, 326, 190, 32, 13, 10, C.white, true);
addText(cover, 'cover_priority_label', 'DISCOVERY PRIORITY', 262, 310, 160, 14, 8, C.cyan, true);
addFit(cover, 'cover_priority', trunc(needText, 120), 262, 326, 270, 32, 10.5, 9, C.white, false);
addText(cover, 'cover_date_label', 'DATE', 548, 310, 100, 14, 8, C.green, true);
addFit(cover, 'cover_date', dateLabel, 548, 326, 122, 32, 12, 9, C.white, true);
addText(cover, 'cover_footer', 'DRAFT FOR DISCUSSION  •  CONFIDENTIAL  •  YOUR AGENCY', 44, 376, 560, 14, 8, C.muted, true);

// ================= content slides =================
const Y = 158, H = 214, X0 = 36, W = 648;
parsed.forEach((s, i) => {
  const n = i + 2, sid = 'deck_slide_' + n, h = s.heading.toLowerCase();
  addBase(sid, n, s.heading, s.headline);
  const items = s.items.length ? s.items : [{ label: 'Next step', text: 'To be validated in technical discovery.', tag: '', numbered: false }];

  if (/future.state/.test(h)) {
    // numbered process line with one card per step
    let steps = items.filter(x => x.numbered);
    if (steps.length < 2) steps = items.slice(0, 5);
    steps = steps.slice(0, 5);
    const count = steps.length, gap = 10, bw = (W - gap * (count - 1)) / count;
    addShape(sid, 'flow_line_' + n, X0 + bw / 2, Y + 15, W - bw, 3, C.line, 'RECTANGLE');
    steps.forEach((st, j) => {
      const x = X0 + j * (bw + gap), acc = j % 2 ? C.cyan : C.green;
      const m = st.text.match(/^([A-Za-z][A-Za-z \/&-]{2,22}):\s+(.+)$/);
      const lab = (st.label && !/^step\b/i.test(st.label)) ? st.label : (m ? m[1] : 'Step ' + (j + 1));
      const body = (st.label && !/^step\b/i.test(st.label)) || !m ? st.text : m[2];
      addBadge(sid, 'flow_dot_' + n + '_' + j, x + bw / 2 - 17, Y, 34, 34, acc, String(j + 1), 13, C.bg);
      addShape(sid, 'flow_card_' + n + '_' + j, x, Y + 44, bw, H - 44, C.panel, 'RECTANGLE');
      addShape(sid, 'flow_top_' + n + '_' + j, x, Y + 44, bw, 3, acc, 'RECTANGLE');
      addFit(sid, 'flow_lab_' + n + '_' + j, lab.toUpperCase(), x + 6, Y + 52, bw - 12, 16, 10, 8, acc, true);
      addFit(sid, 'flow_txt_' + n + '_' + j, trunc(body, 135), x + 6, Y + 70, bw - 12, H - 96, 11.5, 10, C.white, false);
      addChip(sid, 'flow_' + n + '_' + j, x + bw - 4, Y + H - 16, st.tag);
    });
  } else if (/architecture/.test(h)) {
    // simple systems diagram: inputs -> automation hub -> outcomes, then scope and access cards
    const ins = (systems.length ? systems : ['Client systems']).slice(0, 4);
    addShape(sid, 'arch_in_panel_' + n, X0, Y, 200, 106, C.panel, 'ROUND_RECTANGLE');
    addText(sid, 'arch_in_lab_' + n, 'CLIENT SYSTEMS', X0 + 10, Y + 5, 180, 14, 8, C.green, true);
    const chipH = Math.min(20, (106 - 28 - 4 * (ins.length - 1)) / ins.length);
    ins.forEach((sy, j) => addBadge(sid, 'arch_in_' + n + '_' + j, X0 + 12, Y + 24 + j * (chipH + 4), 176, chipH, C.panel2, sy.slice(0, 26), 10, C.white, true, 'ROUND_RECTANGLE'));
    addShape(sid, 'arch_a1_' + n, X0 + 206, Y + 40, 34, 26, C.green, 'RIGHT_ARROW');
    addBadge(sid, 'arch_hub_' + n, X0 + 246, Y + 8, 156, 90, C.green, 'AUTOMATION HUB', 11, C.bg, true, 'ROUND_RECTANGLE');
    addText(sid, 'arch_hub_sub_' + n, 'Rules  •  AI assistance  •  Logging', X0 + 246, Y + 98, 156, 14, 8, C.muted, false, 'CENTER');
    addShape(sid, 'arch_a2_' + n, X0 + 408, Y + 40, 34, 26, C.green, 'RIGHT_ARROW');
    addShape(sid, 'arch_out_panel_' + n, X0 + 448, Y, 200, 106, C.panel, 'ROUND_RECTANGLE');
    addText(sid, 'arch_out_lab_' + n, 'PROPOSED OUTCOMES', X0 + 458, Y + 5, 180, 14, 8, C.cyan, true);
    ['One source of truth', 'Automatic notifications', 'Review and monitoring'].forEach((o, j) => addBadge(sid, 'arch_out_' + n + '_' + j, X0 + 460, Y + 24 + j * 26, 176, 22, C.panel2, o, 10, C.white, true, 'ROUND_RECTANGLE'));
    const rest = items.slice(0, 2);
    rest.forEach((it, j) => addCard(sid, 'arch_card_' + n + '_' + j, X0 + j * (rest.length === 1 ? 0 : 328), Y + 120, rest.length === 1 ? W : 320, H - 120, it.label || (j ? 'To be confirmed' : 'Systems in scope'), trunc(it.text, 230), j ? C.orange : C.green, 11, it.tag));
  } else if (/implementation/.test(h)) {
    // phase chevrons with description and acceptance check
    const ph = items.filter(x => /phase/i.test(x.rawLabel + ' ' + x.text.slice(0, 12))).slice(0, 4);
    const list = ph.length >= 2 ? ph : items.slice(0, 4);
    const count = list.length, gap = 8, bw = (W - gap * (count - 1)) / count;
    list.forEach((it, j) => {
      const x = X0 + j * (bw + gap), acc = j % 2 ? C.cyan : C.green;
      const parts = it.text.split(/\bAcceptance\s*:\s*/i);
      const body = trunc(parts[0], 100), acc_t = parts[1] ? trunc(parts[1], 115) : '';
      const name = clean(it.label.replace(/^phase\s*\d+\s*[—-]?\s*/i, '')) || 'Phase ' + (j + 1);
      addBadge(sid, 'ph_head_' + n + '_' + j, x, Y, bw, 30, acc, 'PHASE ' + (j + 1), 11, C.bg, true, 'HOME_PLATE');
      addShape(sid, 'ph_card_' + n + '_' + j, x, Y + 36, bw, H - 36, C.panel, 'RECTANGLE');
      addFit(sid, 'ph_name_' + n + '_' + j, name, x + 6, Y + 38, bw - 12, 34, 12, 9, C.white, true);
      addFit(sid, 'ph_body_' + n + '_' + j, body, x + 6, Y + 70, bw - 12, acc_t ? 62 : 104, 10.5, 10, C.muted, false);
      if (acc_t) {
        addShape(sid, 'ph_accbar_' + n + '_' + j, x + 8, Y + 134, bw - 16, 1.5, C.line, 'RECTANGLE');
        addText(sid, 'ph_acclab_' + n + '_' + j, 'ACCEPTANCE CHECK', x + 6, Y + 138, bw - 12, 12, 8, acc, true);
        addFit(sid, 'ph_acc_' + n + '_' + j, acc_t, x + 6, Y + 151, bw - 12, H - 153, 10, 9.5, C.white, false);
      }
    });
  } else if (/pain points/.test(h)) {
    // problem -> fix rows with arrow between
    const pairs = [];
    for (let k = 0; k < items.length && pairs.length < 3; k += 2) pairs.push([items[k], items[k + 1]]);
    const rows = pairs.length, gap = 10, rh = (H - gap * (rows - 1)) / rows;
    pairs.forEach((pr, j) => {
      const y = Y + j * (rh + gap);
      addCard(sid, 'prob_' + n + '_' + j, X0, y, 292, rh, 'The problem', trunc(pr[0].text, 150), C.orange, 11.5, pr[0].tag);
      addBadge(sid, 'prob_ic_' + n + '_' + j, X0 + 292 - 28, y + rh - 26, 20, 20, C.orange, '!', 11, C.bg);
      addShape(sid, 'prob_arrow_' + n + '_' + j, X0 + 298, y + rh / 2 - 13, 40, 26, C.green, 'RIGHT_ARROW');
      if (pr[1]) {
        addCard(sid, 'fix_' + n + '_' + j, X0 + 344, y, 304, rh, 'The opportunity', trunc(pr[1].text, 160), C.green, 11.5, pr[1].tag);
        addBadge(sid, 'fix_ic_' + n + '_' + j, X0 + 344 + 304 - 28, y + rh - 26, 20, 20, C.green, '+', 12, C.bg);
      }
    });
  } else if (/recommended solution/.test(h)) {
    const left = items.slice(0, 3), cnt = left.length, g = 9, ch = (H - g * (cnt - 1)) / cnt;
    left.forEach((it, j) => {
      const y = Y + j * (ch + g), acc = j % 2 ? C.cyan : C.green;
      addShape(sid, 'sol_card_' + n + '_' + j, X0, y, 424, ch, C.panel, 'RECTANGLE');
      addBadge(sid, 'sol_num_' + n + '_' + j, X0 + 10, y + ch / 2 - 15, 30, 30, acc, String(j + 1), 13, C.bg);
      addFit(sid, 'sol_lab_' + n + '_' + j, (it.label || 'Workstream ' + (j + 1)).toUpperCase(), X0 + 50, y + 5, 260, 16, 9, 8, acc, true);
      addChip(sid, 'sol_' + n + '_' + j, X0 + 416, y + 7, it.tag);
      addFit(sid, 'sol_body_' + n + '_' + j, trunc(it.text, 195), X0 + 50, y + 22, 366, ch - 26, 11.5, 10, C.white, false);
    });
